<script setup>import {Head,Link,useForm} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Icon from '@/Components/UI/Icon.vue';import HrNav from '../Partials/HrNav.vue';import HrPageHeader from '../Partials/HrPageHeader.vue';import PlanningForm from './PlanningForm.vue';defineOptions({layout:AppLayout});const props=defineProps({shift:Object,employees:[Array,Object],departments:[Array,Object]});const local=v=>v?v.slice(0,16):'';const form=useForm({employee_uuid:props.shift.employee.uuid,department_uuid:props.shift.department_uuid??'',title:props.shift.title??'',starts_at:local(props.shift.starts_at),ends_at:local(props.shift.ends_at),observation:props.shift.observation??''});const submit=()=>form.put(`/administration/planning/${props.shift.uuid}`);</script><template><Head title="Modifier le planning"/><div class="space-y-5"><HrNav/><HrPageHeader :eyebrow="`${shift.employee.employee_number} · Correction auditée`" title="Modifier le créneau" :description="`Affectation de ${shift.employee.name}. Le changement ne déduit aucune absence ni heure supplémentaire.`" icon="edit" tone="sky"><template #actions><Link href="/administration/planning" class="inline-flex h-10 items-center gap-2 rounded-lg border border-gray-200 bg-white px-3 text-sm font-bold text-slate-600 hover:border-cyan-300 hover:text-cyan-600 dark:border-gray-800 dark:bg-gray-950 dark:text-slate-200"><Icon name="arrow-left"/> Retour au planning</Link></template></HrPageHeader><PlanningForm :form="form" :employees="employees" :departments="departments" cancel-href="/administration/planning" submit-label="Enregistrer le créneau" @submit="submit"/></div></template>
